for (const lang of LANGS) {
  const dir = join(ROOT, 'locales', lang);
  mkdirSync(dir, { recursive: true });
  for (const [ns, keys] of Object.entries(D)) {
    const out = {};
    for (const [key, vals] of Object.entries(keys)) {
      const i = LANGS.indexOf(lang);
      let v = vals[i] ?? vals[0];
      // surcharge FR/AR/ES/EN (traductions soignées — placeholders générés ailleurs)
      const ov = (OVERRIDE[ns] ?? {})[key];
      if (ov) v = ov[i] ?? v;
      // stocke plat "a.b.c" pour un routage simple côté serveur
      out[key] = v;
    }
    // clés ajoutées par OVERRIDE (n'existant pas dans D) — 4 langues garanties
    {
      const i = LANGS.indexOf(lang);
      for (const [key, ov] of Object.entries(OVERRIDE[ns] ?? {})) {
        if (!(key in out)) out[key] = ov[i] ?? ov[0];
      }
    }
    writeFileSync(join(dir, `${ns}.json`), JSON.stringify(out, null, 2) + '\n', 'utf8');
    console.log(`✔ locales/${lang}/${ns}.json (${Object.keys(out).length} clés)`);
  }
}
console.log('i18n OK — 4 langues ×', Object.keys(D).length, 'namespaces');
